query:
SELECT ?m ?nis ?coord ?parent ?successor ?dissolved ?pl ?nl ?fr ?en ?mul WHERE {
  { ?m wdt:P31 wd:Q2785216 . }
  UNION
  { ?m wdt:P1567 ?sectionNis ; wdt:P17 wd:Q31 . FILTER(REGEX(?sectionNis, "^[0-9]{5}[A-Z]$")) }
  OPTIONAL { ?m wdt:P1567 ?nis }
  OPTIONAL { ?m wdt:P625 ?coord }
  OPTIONAL { ?m wdt:P131 ?parent . OPTIONAL { ?parent wdt:P1366 ?successor } }
  OPTIONAL { ?m wdt:P576 ?dissolved }
  OPTIONAL { ?m rdfs:label ?pl FILTER(LANG(?pl)="pl") }
  OPTIONAL { ?m rdfs:label ?nl FILTER(LANG(?nl)="nl") }
  OPTIONAL { ?m rdfs:label ?fr FILTER(LANG(?fr)="fr") }
  OPTIONAL { ?m rdfs:label ?en FILTER(LANG(?en)="en") }
  OPTIONAL { ?m rdfs:label ?mul FILTER(LANG(?mul)="mul") }
}
